import{_ as n,C as i,o as r,c as d,j as l,a as t,E as s,w as o,a3 as p}from"./chunks/framework.EDt1A0Ag.js";const P=JSON.parse('{"title":"Shadowrocket 小火箭 iOS 完整保姆级使用教程 2026 · 从下载到进阶分流","description":"2026年最新Shadowrocket (小火箭) iOS保姆级图文教程。涵盖美区Apple ID获取、节点订阅导入、规则分流配置、全局路由、HTTPS解密证书与常见10大报错排查。","frontmatter":{"title":"Shadowrocket 小火箭 iOS 完整保姆级使用教程 2026 · 从下载到进阶分流","description":"2026年最新Shadowrocket (小火箭) iOS保姆级图文教程。涵盖美区Apple ID获取、节点订阅导入、规则分流配置、全局路由、HTTPS解密证书与常见10大报错排查。"},"headers":[],"relativePath":"client/shadowrocket.md","filePath":"client/shadowrocket.md","lastUpdated":1787499481000}'),c={name:"client/shadowrocket.md"},h={class:"flex items-center gap-2 mb-6"};function g(u,a,m,k,S,b){const e=i("LeafBadge");return r(),d("div",null,[a[4]||(a[4]=l("h1",{id:"🚀-shadowrocket-小火箭-ios-完整保姆级使用教程-2026",tabindex:"-1"},[t("🚀 Shadowrocket (小火箭) iOS 完整保姆级使用教程 2026 "),l("a",{class:"header-anchor",href:"#🚀-shadowrocket-小火箭-ios-完整保姆级使用教程-2026","aria-label":'Permalink to "🚀 Shadowrocket (小火箭) iOS 完整保姆级使用教程 2026"'},"​")],-1)),l("div",h,[s(e,{variant:"primary"},{default:o(()=>[...a[0]||(a[0]=[t("iOS 必备工具",-1)])]),_:1}),s(e,{variant:"wood"},{default:o(()=>[...a[1]||(a[1]=[t("规则智能分流",-1)])]),_:1}),s(e,{variant:"accent"},{default:o(()=>[...a[2]||(a[2]=[t("3分钟上手",-1)])]),_:1}),s(e,{variant:"amber"},{default:o(()=>[...a[3]||(a[3]=[t("2026 最新版",-1)])]),_:1})]),a[5]||(a[5]=p(`<p><strong>Shadowrocket</strong>（中文俗称“小火箭”）是 iOS / iPadOS 平台上最为经典、性能最强悍的代理客户端之一。它具备极高的网络吞吐效率、精细的规则分流引擎以及对 Shadowsocks、VLESS、Trojan、Hysteria2 等全协议的原生支持。</p><p>本教程为 2026 全新重构版，旨在帮助<strong>零基础小白</strong>在 3 分钟内完成配置，同时为<strong>进阶用户</strong>提供分流、证书与省电优化指引。</p><hr><h2 id="🎯-学习目标与准备工作" tabindex="-1">🎯 学习目标与准备工作 <a class="header-anchor" href="#🎯-学习目标与准备工作" aria-label="Permalink to &quot;🎯 学习目标与准备工作&quot;">​</a></h2><h3 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h3><ul><li>成功在 iPhone / iPad 上安装并激活 Shadowrocket；</li><li>正确导入机场订阅链接并完成节点测速与连接；</li><li>掌握「配置（规则分流）」与「代理（全局代理）」的适用场景；</li><li>解决连接后微信发不出图片、国内 App 变慢或节点全部超时的常见问题。</li></ul><h3 id="_2-准备工作清单" tabindex="-1">2. 准备工作清单 <a class="header-anchor" href="#_2-准备工作清单" aria-label="Permalink to &quot;2. 准备工作清单&quot;">​</a></h3><ul><li>一台运行 iOS 12.0 或更高版本的 iPhone / iPad；</li><li>一个<strong>非中国大陆地区</strong>的 Apple ID（如美区、日区、港区 Apple ID，用于在 App Store 购买下载，官方售价 $2.99）；</li><li>一个有效的机场订阅链接（如 <a href="/ranking/guangsu">光速云 (👑全网主推第一)</a> 或 <a href="/ranking/">飞猫云 (🥈低价年付)</a> 提供的订阅 URL）。</li></ul><hr><h2 id="📱-第一阶段-下载与安装-shadowrocket" tabindex="-1">📱 第一阶段：下载与安装 Shadowrocket <a class="header-anchor" href="#📱-第一阶段-下载与安装-shadowrocket" aria-label="Permalink to &quot;📱 第一阶段：下载与安装 Shadowrocket&quot;">​</a></h2><blockquote><p>⚠️ <strong>新手避坑提示</strong>：中国大陆 App Store 无法搜索到正版 Shadowrocket。任何在国区 App Store 搜索到的类似名字或收费软件均为仿冒山寨应用！</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 步骤 1: 打开 App Store -&gt; 点击右上角头像 -&gt; 滑到底部退出登录  │</span></span>
<span class="line"><span>│ 步骤 2: 登录你的【美区/港区 Apple ID】 (切勿在设置中登录 iCloud)│</span></span>
<span class="line"><span>│ 步骤 3: 搜索 &quot;Shadowrocket&quot; (认准开发者: Shadow Launch Tech)│</span></span>
<span class="line"><span>│ 步骤 4: 下载安装完成后，可在 App Store 切回自己的国区账号      │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="⚡-第二阶段-导入机场订阅链接-两种方式" tabindex="-1">⚡ 第二阶段：导入机场订阅链接 (两种方式) <a class="header-anchor" href="#⚡-第二阶段-导入机场订阅链接-两种方式" aria-label="Permalink to &quot;⚡ 第二阶段：导入机场订阅链接 (两种方式)&quot;">​</a></h2><h3 id="方式-a-一键导入-最推荐-耗时-5-秒" tabindex="-1">方式 A：一键导入（最推荐，耗时 5 秒） <a class="header-anchor" href="#方式-a-一键导入-最推荐-耗时-5-秒" aria-label="Permalink to &quot;方式 A：一键导入（最推荐，耗时 5 秒）&quot;">​</a></h3><ol><li>使用 iPhone 的 Safari 浏览器登录机场后台（例如登录 <a href="https://sahude.gsyvipaff.com/#/?code=keqgvT5Y" target="_blank" rel="nofollow sponsored noopener">光速云用户中心</a>）；</li><li>找到【一键导入订阅】按钮，在弹出的选项中点击【导入到 Shadowrocket】；</li><li>系统会自动唤起小火箭应用，并在弹窗中提示“已成功添加订阅”，点击【保存】即可。</li></ol><h3 id="方式-b-手动复制链接导入" tabindex="-1">方式 B：手动复制链接导入 <a class="header-anchor" href="#方式-b-手动复制链接导入" aria-label="Permalink to &quot;方式 B：手动复制链接导入&quot;">​</a></h3><ol><li>在机场后台复制【Shadowrocket 订阅链接】或【通用订阅链接】；</li><li>打开 Shadowrocket，点击右上角的 <strong>➕ 号</strong>；</li><li>在【类型】中选择 <strong>Sub (Subscribe / 订阅)</strong>；</li><li>在【URL】一栏长按粘贴刚刚复制的订阅链接；</li><li>在【备注】一栏输入机场名称（如 <code>光速云</code>），点击右上角【保存】；</li><li>软件会自动向服务器拉取最新节点列表。</li></ol><hr><h2 id="🧭-第三阶段-全局路由模式与日常使用" tabindex="-1">🧭 第三阶段：全局路由模式与日常使用 <a class="header-anchor" href="#🧭-第三阶段-全局路由模式与日常使用" aria-label="Permalink to &quot;🧭 第三阶段：全局路由模式与日常使用&quot;">​</a></h2><p>在 Shadowrocket 首页中央，有四种【全局路由】模式，请根据你的使用需求正确选择：</p><table tabindex="0"><thead><tr><th style="text-align:left;">路由模式</th><th style="text-align:left;">工作原理</th><th style="text-align:left;">推荐使用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>配置 (Config)</strong> ⭐ 默认推荐</td><td style="text-align:left;">根据内置分流规则判断：国内流量直连、国外被阻断网站走代理</td><td style="text-align:left;"><strong>99% 日常使用场景</strong>。既不影响微信/淘宝/美团速度，又能流畅访问 Google/ChatGPT。</td></tr><tr><td style="text-align:left;"><strong>代理 (Proxy)</strong></td><td style="text-align:left;">所有流量无论国内外，全部强制走选中的代理节点</td><td style="text-align:left;">遇到特定国外网站打不开、或需要临时将 IP 伪装成海外机房时使用。</td></tr><tr><td style="text-align:left;"><strong>直连 (Direct)</strong></td><td style="text-align:left;">所有流量全部不经过代理，直接由本地网络发起连接</td><td style="text-align:left;">相当于关闭代理软件，排查本地宽带故障时使用。</td></tr><tr><td style="text-align:left;"><strong>场景 (Scene)</strong></td><td style="text-align:left;">根据连接的 Wi-Fi SSID 或蜂窝网络自动切换不同路由规则</td><td style="text-align:left;">进阶办公场景，如公司内网自动直连，外部网络走代理。</td></tr></tbody></table><hr><h2 id="🛠️-第四阶段-一键启动与系统-vpn-权限授权" tabindex="-1">🛠️ 第四阶段：一键启动与系统 VPN 权限授权 <a class="header-anchor" href="#🛠️-第四阶段-一键启动与系统-vpn-权限授权" aria-label="Permalink to &quot;🛠️ 第四阶段：一键启动与系统 VPN 权限授权&quot;">​</a></h2><ol><li>在节点列表中点击选择一个低延迟节点（如 <code>香港专线01</code> 或 <code>日本01</code>）；</li><li>拨动顶部的 <strong>【未连接 / 已连接】主开关</strong>；</li><li>如果是首次使用，iOS 系统会弹出系统弹窗：<code>“Shadowrocket”想要添加 VPN 配置</code>；</li><li>点击 <strong>【允许】</strong>，并通过 iPhone 的 <strong>面容 ID (Face ID)</strong> 或输入锁屏密码进行授权；</li><li>当手机状态栏右上角或控制中心出现 <strong>[VPN]</strong> 小图标时，即代表已成功开启代理！</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     [iPhone 屏幕]</span></span>
<span class="line"><span>┌─────────────────────────┐</span></span>
<span class="line"><span>│  Shadowrocket      🌿   │</span></span>
<span class="line"><span>│  状态: [ 已连接  ● ]    │  &lt;-- 拨动此处开启</span></span>
<span class="line"><span>│  全局路由: [ 配置 ▾ ]   │  &lt;-- 保持“配置”模式</span></span>
<span class="line"><span>│                         │</span></span>
<span class="line"><span>│  服务器节点:            │</span></span>
<span class="line"><span>│  ● 🇭🇰 香港 IEPL 专线 01 │  &lt;-- 点击选中</span></span>
<span class="line"><span>│  ○ 🇯🇵 日本 专线 02      │</span></span>
<span class="line"><span>│  ○ 🇸🇬 新加坡 专线 03    │</span></span>
<span class="line"><span>└─────────────────────────┘</span></span></code></pre></div><hr><h2 id="🚀-进阶技巧-订阅自动更新与测速排序" tabindex="-1">🚀 进阶技巧：订阅自动更新与测速排序 <a class="header-anchor" href="#🚀-进阶技巧-订阅自动更新与测速排序" aria-label="Permalink to &quot;🚀 进阶技巧：订阅自动更新与测速排序&quot;">​</a></h2><h3 id="_1-开启节点自动更新" tabindex="-1">1. 开启节点自动更新 <a class="header-anchor" href="#_1-开启节点自动更新" aria-label="Permalink to &quot;1. 开启节点自动更新&quot;">​</a></h3><p>为防止机场更换节点服务器导致断连，建议开启自动定时更新：</p><ul><li>点击底部【设置】 -&gt; 【订阅】；</li><li>勾选 <strong>【打开时更新】</strong> 与 <strong>【后台自动更新】</strong>。</li></ul><h3 id="_2-节点连通性测速" tabindex="-1">2. 节点连通性测速 <a class="header-anchor" href="#_2-节点连通性测速" aria-label="Permalink to &quot;2. 节点连通性测速&quot;">​</a></h3><ul><li>在首页点击【连通性测试】 -&gt; 选择【测试方法：TCP / ICMP / HTTPS】；</li><li>稍等 2 秒，每个节点后方会显示具体的毫秒延迟（如 <code>25ms</code> 为极佳，<code>Timeout</code> 为超时）。</li></ul><hr><h2 id="❓-shadowrocket-常见-10-大疑问与排错解答-faq" tabindex="-1">❓ Shadowrocket 常见 10 大疑问与排错解答 (FAQ) <a class="header-anchor" href="#❓-shadowrocket-常见-10-大疑问与排错解答-faq" aria-label="Permalink to &quot;❓ Shadowrocket 常见 10 大疑问与排错解答 (FAQ)&quot;">​</a></h2><details class="details custom-block"><summary>1. 为什么连上小火箭后微信发不出图片、美团无法定位？</summary><p><strong>根因</strong>：你的全局路由模式被误选为了【代理】而非【配置】。<br><strong>解决方法</strong>：在小火箭首页将【全局路由】切回 <strong>【配置 (Config)】</strong>，国内 App 流量将自动直连，不再走海外节点。</p></details><details class="details custom-block"><summary>2. 为什么所有节点测速都显示“Timeout”全红？</summary><p><strong>根因</strong>：通常为系统时间不同步或订阅链接失效。<br><strong>解决步骤</strong>：</p><ol><li>打开 iPhone【设置】-&gt;【通用】-&gt;【日期与时间】，开启【自动设置】确保时间精确；</li><li>在小火箭中找到订阅分组，左滑点击【更新】拉取最新节点。</li></ol></details><details class="details custom-block"><summary>3. 可以在淘宝或拼多多买共享 Apple ID 下载小火箭吗？</summary><p>可以购买带有 Shadowrocket 兑换码或已购小火箭的独享 ID，但<strong>切记严禁在 iPhone【设置】顶部的 iCloud 登录别人的账号</strong>（会导致手机被远程锁死为砖头）。必须且仅能在 <strong>【App Store】</strong> 商店内登录下载。</p></details><details class="details custom-block"><summary>4. 小火箭耗电量看起来很高，正常吗？</summary><p>iOS 系统的电池统计机制会将所有经过小火箭代理转发的流量（如刷 YouTube 4K、TikTok 视频产生的耗电）统一计入 Shadowrocket 名下。实际上小火箭本身 CPU 占用率极低（&lt; 2%），无需担心异常耗电。</p></details><details class="details custom-block"><summary>5. 如何配置 ChatGPT / OpenAI 专用分流规则？</summary><p>在【配置】页面长按默认配置文件 <code>default.conf</code> -&gt; 点击【编辑配置】 -&gt; 添加规则：<code>DOMAIN-KEYWORD, openai, PROXY</code> 和 <code>DOMAIN-SUFFIX, chatgpt.com, PROXY</code>，确保流量必定经过支持 AI 解锁的专线节点（如 <a href="/ranking/guangsu">光速云</a>）。</p></details><details class="details custom-block"><summary>6. 开启小火箭后能否开启手机个人热点给电脑用？</summary><p>可以。在小火箭【设置】中开启【允许来自局域网的连接】，记录下显示的代理端口（默认 <code>1082</code>），电脑连接手机热点后在电脑端配置该局域网代理即可共享出海。</p></details><details class="details custom-block"><summary>7. 小火箭支持哪些协议？</summary><p>Shadowrocket 支持业界全主流协议，包括 Shadowsocks、ShadowsocksR、VLESS、VMess、Trojan、Snell、SOCKS5、HTTP 以及最新的 Hysteria2 与 TUIC。</p></details><details class="details custom-block"><summary>8. 为什么有的节点看不了 Netflix 原画非自制剧？</summary><p>Netflix 会对公共机房 IP 进行严格封锁。若要观看全区片库，请在节点列表中选择标注有 <code>原生 / 解锁 / 流媒体</code> 的专用专线节点（如 <a href="/ranking/guangsu">光速云 70节点全解锁</a>）。</p></details><details class="details custom-block"><summary>9. 小火箭的 HTTPS 解密证书有什么用？</summary><p>HTTPS 解密用于抓包分析和去除特定网页广告。对于单纯科学上网、查资料、看视频的普通用户，<strong>完全不需要安装证书</strong>，保持默认关闭即可。</p></details><details class="details custom-block"><summary>10. 如何在不同 Wi-Fi 环境下自动开关代理？</summary><p>点击底部【配置】-&gt; 切换到【场景】模式，可以针对家里的 Wi-Fi、公司 Wi-Fi 和蜂窝移动网络分别指定启用或直连规则，实现完全无感自动化。</p></details>`,45))])}const y=n(c,[["render",g]]);export{P as __pageData,y as default};
